export const GLOSSARY_SHARD = Object.freeze({"cryptocurrency":{"slug":"cryptocurrency","cat":"basics","en":"Cryptocurrency","contentLocale":"zh-Hans","term":"加密货币（Cryptocurrency）","aka":["数字货币","虚拟货币","Crypto"],"short":"加密货币是依靠密码学和区块链记账、无需银行等中心机构即可点对点转移的数字资产，比特币是第一个加密货币。","body":[["加密货币的余额不是存在某家银行里，而是记录在",["区块链","blockchain"],"上。你掌握",["私钥","private-key"],"，就能签名转账；网络",["节点","node"],"验证签名有效后，把交易写进账本。这让跨境转账可以 7×24 小时进行，但也意味着丢了私钥或",["助记词","seed-phrase"],"，没有客服能帮你找回。"],["市面上的加密货币大致可分几类：",["比特币","bitcoin"],"这类主打价值储存的；",["以太坊","ethereum"],"、Solana 这类支撑智能合约的公链原生币；USDT、USDC 这类锚定法币的稳定币；以及各种应用代币和 Meme 币。它们的用途、供应规则和风险差别很大。"],"多数人通过中心化交易所买卖加密货币，币放在交易所账户里由平台托管；也可以提到自己的钱包自行保管。各国对加密货币的监管和税务规定不同，交易前应了解所在地的规则。"],"example":"假设你用 1,000 USDT 在现货市场买入 ETH，成交价为 2,500 USDT，扣除 0.1% 手续费 1 USDT 后，你得到约 0.3996 ETH。如果之后 ETH 跌到 2,000 USDT，这些币价值约 799 USDT，账面亏损约 201 USDT；涨到 3,000 USDT 则价值约 1,199 USDT。价格每天上下 5% 以上在加密货币里并不少见。","mistakes":["以为所有加密货币都像比特币一样有固定上限，很多代币可以持续增发。","把助记词截图存在手机相册或发给“客服”，导致资产被盗。","只看价格低就买，忽略了流通量、流动性和项目是否还在运营。"],"faq":[{"q":"加密货币和数字人民币一样吗？","a":"不一样。数字人民币由中国人民银行发行，属于法定货币的数字形式；加密货币一般由去中心化网络或私人机构发行，价格随市场波动。"},{"q":"可以只买一小部分比特币吗？","a":"可以。1 枚比特币可以拆分到 1 亿分之一（1 聪），交易所通常允许你用很小的金额买入零头。"}],"title":"什么是加密货币？含义、种类与基本风险","description":"加密货币是什么、和银行存款有何不同、常见的几大类别，以及新手在交易所买卖和自己保管时最容易踩的坑，一篇看懂。","related":[["blockchain","区块链（Blockchain）","区块链是一种由众多节点共同维护、按时间顺序把交易打包成区块并用密码学串联起来的公开账本，写入后极难篡改。"],["bitcoin","比特币（Bitcoin，BTC）","比特币是 2009 年上线的第一个去中心化加密货币，总量上限 2100 万枚，通过工作量证明挖矿维护网络，代号 BTC。"],["altcoin","山寨币（Altcoin）","山寨币是指比特币以外的所有加密货币，包括以太坊、Solana 等公链币，也包括各种应用代币和 Meme 币。"],["stablecoin","稳定币（Stablecoin）","稳定币是一种设计为与美元等法币或资产保持稳定兑换比例的加密货币，最常见的是 1 枚兑 1 美元的 USDT 和 USDC，是加密交易中的主要计价和结算工具。"],["centralized-exchange","中心化交易所（CEX）","中心化交易所（CEX）是由公司运营、托管用户资产并撮合买卖订单的加密货币交易平台，如币安、OKX、Bybit、Bitget。"]],"lesson":{"id":"E01","slug":"can-i-buy-part-of-a-bitcoin","ep":1,"title":"一枚比特币太贵，我就不能买吗？"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"smart-contract":{"slug":"smart-contract","cat":"basics","en":"Smart contract","contentLocale":"zh-Hans","term":"智能合约（Smart Contract）","aka":["Smart Contract","合约"],"short":"智能合约是部署在区块链上、满足预设条件就自动执行的程序代码，DeFi、NFT 和链上代币都依靠它运行。","body":[["智能合约本质上是一段放在链上的代码。比如一个兑换合约规定：你转入 A 代币，它就按池子里的比例自动转出 B 代币。整个过程不需要人工审核，执行结果写进",["区块链","blockchain"],"，任何人都能查到。"],"合约一旦部署，代码通常难以修改，漏洞也会跟着一直存在。历史上出现过不少因合约漏洞或权限设计不当导致资金被盗的事件。有些合约保留了管理员权限，可以升级或暂停，这既方便修复问题，也带来项目方作恶的可能。","你在钱包里点“授权”（Approve）时，就是允许某个合约动用你的代币。授权额度设为无限、或授权给来路不明的合约，是常见的资产被盗原因。定期检查并撤销不再使用的授权是好习惯。"],"example":["假设你在",["去中心化交易所","dex"],"把 1,000 ",["USDC","usdc"]," 换成 ",["ETH","ethereum"],"，ETH 价格 2,500 USDC。第一步，你签名授权合约使用 1,000 USDC，付一次 Gas；第二步，合约执行兑换，按池子报价给你约 0.398 ETH（扣掉 0.3% 交易费和少量",["滑点","slippage"],"），再付一次 Gas。若你当初授权的是无限额度，这个合约以后仍可动用你钱包里的全部 USDC。"],"mistakes":["随手签署“无限授权”，给钓鱼或有漏洞的合约留下后门。","以为经过审计的合约就绝对安全，审计只能降低而不能消除风险。","不看合约地址，和仿冒的同名合约交互。"],"faq":[{"q":"智能合约是合同吗？","a":"不是法律意义上的合同，而是自动执行的程序。它“智能”在于条件满足就自动运行，而不是能理解复杂的法律条款。"},{"q":"智能合约能被修改吗？","a":"取决于设计。不可升级的合约部署后无法修改，可升级合约则由持有管理权限的地址进行更新，这时要关注谁控制这个权限。"}],"title":"什么是智能合约？含义、用途与授权风险","description":"智能合约是什么？用例子讲清合约如何自动执行、为什么一旦部署难以修改，以及钱包里的合约授权（Approve）有哪些风险。","related":[["ethereum","以太坊（Ethereum，ETH）","以太坊是支持智能合约的开源区块链，原生币为 ETH，用于支付 Gas 费和质押，DeFi、NFT 和大量代币都运行在它上面。"],["defi","DeFi（去中心化金融）","DeFi（去中心化金融）是指运行在区块链智能合约上的金融服务，比如交易、借贷、质押和收益聚合，用户用自己的钱包直接参与，无需银行或交易所作为中介。"],["token-approval","代币授权（Token Approval）","代币授权是你在链上允许某个智能合约动用你钱包里指定代币的操作，授权额度决定合约最多能转走多少，常用于 DEX 交易和 DeFi 存款。"],["oracle","预言机（Oracle）","预言机是把链下数据（如币价、汇率、体育比分）传送到区块链上供智能合约使用的服务，DeFi 借贷、衍生品和稳定币都依赖它获取价格。"],["gas-fee","Gas 费（Gas Fee）","Gas 费是在以太坊等区块链上发送交易或调用智能合约时支付给网络的手续费，用链的原生币结算，高低取决于操作复杂度和网络拥堵。"]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"gas-fee":{"slug":"gas-fee","cat":"basics","en":"Gas fee","contentLocale":"zh-Hans","term":"Gas 费（Gas Fee）","aka":["Gas","矿工费","网络手续费","Gas fee"],"short":"Gas 费是在以太坊等区块链上发送交易或调用智能合约时支付给网络的手续费，用链的原生币结算，高低取决于操作复杂度和网络拥堵。","body":[["在",["以太坊","ethereum"],"上，每个操作都要消耗一定量的 Gas：普通 ETH 转账固定为 21,000 Gas，代币转账和 ",["DeFi","defi"]," 操作消耗更多。你实际支付的费用 = 消耗的 Gas × Gas 价格，Gas 价格以 gwei 计（1 gwei = 0.000000001 ETH），由基础费和给出块者的小费组成。"],["网络越拥堵，基础费越高。热门项目上线、行情剧烈波动时，Gas 价格可能在短时间内翻好几倍。交易失败时 Gas 通常不会退还，因为",["节点","node"],"已经执行了计算。"],["在",["交易所","centralized-exchange"],"提币时，你看到的是交易所收取的",["提币手续费","withdrawal-fee"],"，它可能和链上实际 Gas 不同，各平台定价方式不一样。不同链上的 Gas 也用不同的币支付：以太坊和多数 L2 用 ETH，BNB Chain 用 BNB，Solana 用 SOL。"]],"example":["假设你要在以太坊上转一笔 ",["USDT","usdt"],"，消耗约 65,000 Gas。如果基础费 15 gwei、小费 1 gwei，总价 16 gwei，费用 = 65,000 × 16 = 1,040,000 gwei = 0.00104 ETH。ETH 价格 2,800 USDT 时约 2.91 USDT。若网络拥堵、Gas 价格涨到 60 gwei，同一笔转账就要约 10.9 USDT。"],"mistakes":["钱包里只有代币没有原生币，导致交易无法发出。","把 Gas 上限设得太低，交易执行到一半失败，已消耗的 Gas 不退。","拥堵时反复加价重发，结果多付了好几次手续费。"],"faq":[{"q":"Gas 费为什么有时很贵有时很便宜？","a":"Gas 价格由供需决定。链上交易多、区块空间紧张时，大家抬价争抢打包，费用就上涨；网络空闲时则较低。"},{"q":"交易失败了 Gas 费会退吗？","a":"一般不会。节点已经为执行这笔交易付出了计算，失败交易消耗的 Gas 仍要支付，只有未使用的部分不扣。"}],"title":"什么是 Gas 费？Gas 费的含义与计算方法","description":"Gas 费是什么？用例子讲清 Gas 费等于消耗量乘 Gas 价格、gwei 怎么换算、为什么拥堵时变贵，以及失败交易为何仍扣费。","related":[["layer-2","二层网络（Layer 2，L2）","二层网络（L2）是建立在一层区块链之上的扩容方案，在二层批量处理交易后把结果提交回主链，以更低的费用借用主链安全性。"],["mempool","内存池（Mempool）","内存池是区块链节点用来暂存已广播但尚未被打包进区块的交易的等待区，交易在这里排队，矿工或验证者通常优先打包手续费更高的交易。"],["withdrawal-fee","提币手续费（Withdrawal fee）","提币手续费是你把加密资产从交易所转出到外部地址时，交易所收取的费用，通常按币种和网络收取固定数量，用于覆盖链上Gas费和平台的处理成本。"],["ethereum","以太坊（Ethereum，ETH）","以太坊是支持智能合约的开源区块链，原生币为 ETH，用于支付 Gas 费和质押，DeFi、NFT 和大量代币都运行在它上面。"],["smart-contract","智能合约（Smart Contract）","智能合约是部署在区块链上、满足预设条件就自动执行的程序代码，DeFi、NFT 和链上代币都依靠它运行。"]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"转账之前，这几项一个也别猜"},"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"bull-market":{"slug":"bull-market","cat":"basics","en":"Bull market","contentLocale":"zh-Hans","term":"牛市（Bull Market）","aka":["Bull market","牛市行情"],"short":"牛市是指加密货币或其他资产价格在较长时间内持续上涨、成交活跃、市场情绪普遍乐观的阶段，与之相对的是熊市。","body":[["牛市没有官方定义，传统市场常用“从低点上涨 20% 以上”作为粗略标准，但加密市场波动更大，大家更多看整体趋势：价格不断创出更高的高点和更高的低点，",["成交量","trading-volume"],"放大，新用户和新资金涌入。"],["牛市中也会有剧烈回调。加密市场在上涨趋势里出现 20% 到 30% 的回撤并不罕见，高",["杠杆","leverage"],"多单在这种回调里容易被",["强平","liquidation"],"。所以“牛市”只描述大方向，不保证每笔交易都赚钱。"],["牛市阶段情绪容易过热，",["FOMO","fomo"]," 推着人追高，各种新币、高收益产品层出不穷。没有人能准确判断牛市从哪天开始、到哪天结束，常见做法是事先定好仓位上限和分批止盈计划，而不是凭情绪加仓。"]],"example":["假设某币从 20 ",["USDT","usdt"]," 涨到 50 USDT，属于明显的牛市趋势。中途价格从 45 USDT 回调到 34 USDT，跌幅约 24%。如果你在 45 USDT 开了 5 倍杠杆多单，价格下跌约 20% 时就接近",["强平价","liquidation-price"],"（未计费用），这次回调就足以让你爆仓，即使之后价格又涨回 50 USDT。"],"mistakes":["以为牛市里只涨不跌，满仓加高杠杆追涨。","因为身处牛市就忽视止损和仓位管理。","把短期反弹当成牛市开始，过早重仓。"],"faq":[{"q":"牛市和熊市怎么区分？","a":"牛市是价格持续上涨、情绪乐观的阶段，熊市是价格持续下跌、情绪悲观的阶段。两者通常要回头看才能确认，身处其中时很难精确判断。"},{"q":"牛市一般持续多久？","a":"没有固定周期。过去的加密牛市长短不一，宏观环境、资金面和行业事件都会影响，不能简单套用历史时间。"}],"title":"什么是牛市？加密货币牛市的含义与特点","description":"牛市是什么意思？讲清加密货币牛市的特征、为什么牛市中也会出现大幅回调，以及高杠杆在牛市回撤中如何导致爆仓。","related":[["bear-market","熊市（Bear Market）","熊市是指加密货币或其他资产价格在较长时间内持续下跌、市场情绪悲观、成交量和关注度明显下降的阶段，与之相对的是牛市。"],["fomo","FOMO（错失恐惧）","FOMO（Fear of Missing Out）指害怕错过上涨行情而冲动买入的心理，在币圈常表现为追高和临时加仓。"],["all-time-high","历史最高价（ATH）","历史最高价（ATH，All-Time High）是某个资产自上市交易以来曾达到的最高价格，创新高即价格突破这一纪录。"],["fear-and-greed-index","恐惧与贪婪指数（Fear and Greed Index）","恐惧与贪婪指数是把价格波动、成交量、社交媒体热度、资金费率等数据综合成0到100分数的市场情绪指标，分数越低代表越恐惧，越高代表越贪婪。"]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"take-profit":{"slug":"take-profit","cat":"trading","en":"Take-profit order","contentLocale":"zh-Hans","term":"止盈单（Take-Profit）","aka":["止盈","Take profit","TP"],"short":"止盈单是预先设定目标价，当价格朝有利方向达到该价位时自动卖出（或平仓）锁定利润的订单。","body":[["止盈单和",["止损单","stop-loss"],"方向相反：止损在价格不利时保护本金，止盈在价格有利时兑现利润。止盈通常也是条件单，触发后以市价或限价执行。在",["合约交易","futures-contract"],"中，开仓时可以同时设置止盈和止损。"],"提前设好止盈能减少情绪干扰。很多人在行情上涨时越看越贪，原本计划在 20% 获利了结，结果一直拿着，最后利润回吐甚至转为亏损。",["止盈不一定要一次全部卖出，可以分批：比如到第一目标卖一半，剩下的用",["移动止损","trailing-stop"],"跟踪。止盈目标通常和止损距离一起考虑，形成",["盈亏比","risk-reward-ratio"],"，例如冒 1 份风险去追求 2 到 3 份收益。"]],"example":["假设你在 1.20 ",["USDT","usdt"]," 买入 2,000 枚某币，止损设在 1.12（风险 160 USDT）。你设两个止盈：1.36 卖 1,000 枚，盈利 160 USDT；1.44 卖剩下的 1,000 枚，再盈利 240 USDT。如果两档都成交，总盈利 400 USDT，是风险的 2.5 倍。如果只到第一档就回落到成本价，你仍锁定了 160 USDT。"],"mistakes":["只设止损不设止盈，赚到的利润最后全部回吐。","止盈目标随意设定，和止损距离不成比例。","价格接近止盈时又把止盈往上挪，最终错过离场机会。"],"faq":[{"q":"止盈和止损可以同时设置吗？","a":"可以。多数交易所在合约和部分现货下单界面都支持同时设置止盈止损，现货也可以用 OCO 单实现。"},{"q":"止盈设多少合适？","a":"没有固定比例。常见方法是参考阻力位或前高，并保证止盈距离与止损距离的盈亏比合理。"}],"title":"什么是止盈单？止盈的含义与设置技巧","description":"止盈单是什么意思？讲清止盈如何锁定利润、为什么要分批止盈、怎样结合止损计算盈亏比，以及新手常见的止盈错误。","related":[["stop-loss","止损单（Stop-Loss）","止损单是预先设定一个触发价，当价格不利地达到该价位时自动卖出（或平仓）以限制亏损的订单。"],["oco-order","OCO 订单（二选一订单）","OCO 订单（One-Cancels-the-Other）是把两笔订单绑定在一起，其中一笔成交后另一笔自动撤销，常用于同时设置止盈和止损。"],["risk-reward-ratio","盈亏比（Risk-Reward Ratio）","盈亏比是一笔交易计划中可能亏损的金额与可能盈利的金额之比，例如止损亏 100、止盈赚 300，就是 1:3 的盈亏比。"],["limit-order","限价单（Limit Order）","限价单是指定价格买入或卖出的订单，只在市场价格达到或优于你设定的价格时才成交，可能部分成交或一直不成交。"]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"止盈止损，是计划，不是保险"},"coin":null,"tool":null,"cta":false},"margin-trading":{"slug":"margin-trading","cat":"derivatives","en":"Margin trading","contentLocale":"zh-Hans","term":"杠杆交易（Margin Trading）","aka":["保证金交易","现货杠杆","借贷交易","margin trading"],"short":"杠杆交易是用自己的资金作保证金，向交易所借入资金或币来放大买卖规模的交易方式，借款要付利息，亏损到一定程度会被强平。","body":[["在",["交易所","centralized-exchange"],"的现货杠杆账户里，你可以借入 ",["USDT","usdt"]," 买更多币（做多），也可以借入币先卖出（做空）。借款按小时或按天计息，利率随币种和市场供需变化。",["合约交易","futures-contract"],"同样基于保证金，但不需要真正借币，所以广义上也被称为保证金交易。"],["杠杆交易的风险控制依赖保证金率或风险率：账户资产相对负债越少，风险越高，跌到交易所设定的线时会先提醒，再触发",["强平","liquidation"],"。具体指标叫法和计算方式各家不同，要看清楚交易所的说明。"],"相比合约，现货杠杆的优点是买入的是真实的币，缺点是要付借款利息，而且很多小币借不到。是否允许你使用杠杆交易，也取决于所在地区的监管和交易所的产品设置。"],"example":["假设你有 5,000 USDT，在现货杠杆账户用 3 倍",["杠杆","leverage"],"借入 10,000 USDT，共买入 15,000 USDT 的 ",["BTC","bitcoin"],"，即 BTC 60,000 时买 0.25 个。若日利率 0.02%，每天利息约 2 USDT。BTC 上涨 10%，持仓价值 16,500，还掉 10,000 借款后剩 6,500，收益 30%；下跌 10%，只剩 3,500，亏损 30%。"],"mistakes":["忘了借款利息每天都在累积，长期持仓的成本被低估。","把杠杆账户和现货账户混为一谈，以为买到的币不会被强平。","借币做空时没考虑某些币可借数量少、利率可能突然上升。"],"faq":[{"q":"杠杆交易和合约交易有什么区别？","a":"现货杠杆是真实借钱或借币买卖现货，需要付利息；合约交易不借币，通过保证金对价格涨跌下注，持仓成本主要是资金费。两者都会被强平。"},{"q":"杠杆交易会亏得比本金多吗？","a":"正常情况下交易所会在亏完前强平。但在极端行情中如果平仓价格比预期更差，有可能出现穿仓，各交易所对穿仓损失的处理方式不同。"}],"title":"杠杆交易是什么？现货杠杆借贷怎么运作","description":"解释加密货币杠杆交易（保证金交易）如何借币放大仓位、利息怎么计算、何时会被强平，以及它与合约交易的主要区别。","related":[["leverage","杠杆（Leverage）","杠杆是用较少的保证金控制较大仓位的方式，例如 10 倍杠杆意味着 1,000 USDT 保证金可以开出价值 10,000 USDT 的仓位，盈亏同样按仓位价值计算。"],["initial-margin","初始保证金（Initial Margin）","初始保证金是开立一笔杠杆或合约仓位时必须冻结的最低资金，等于仓位价值除以杠杆倍数，杠杆越高，所需初始保证金越少。"],["maintenance-margin","维持保证金（Maintenance Margin）","维持保证金是持有合约仓位所需的最低保证金，当仓位的保证金余额（含未实现盈亏）跌到这个水平时，交易所会触发强制平仓。"],["liquidation","强平（Liquidation）","强平（俗称爆仓）是指杠杆或合约仓位的保证金因亏损低于维持保证金要求时，交易所系统自动强制平掉该仓位，以防亏损超过保证金。"],["cross-margin","全仓保证金（Cross Margin）","全仓保证金是一种保证金模式，账户内所有可用余额共同为全部全仓仓位提供保证金，抗波动能力更强，但一旦强平可能亏掉整个账户余额。"]],"lesson":{"id":"E19","slug":"what-leverage-does","ep":19,"title":"10倍杠杆，是钱变多，还是风险变大？"},"coin":null,"tool":null,"cta":false},"non-custodial-wallet":{"slug":"non-custodial-wallet","cat":"wallets-security","en":"Non-custodial (self-custody) wallet","contentLocale":"zh-Hans","term":"非托管钱包（自托管钱包）","aka":["自托管钱包","去中心化钱包","Non-custodial wallet","Self-custody wallet"],"short":"非托管钱包是由你自己保管私钥或助记词的钱包，资产的控制权完全在你手里，没有任何平台能替你冻结、挪用或找回。","body":[["在",["交易所","centralized-exchange"],"里，你看到的余额其实是平台替你保管的，这叫托管。非托管钱包则相反：钱包软件只是一个工具，真正决定资产归属的是",["私钥","private-key"],"，而私钥只存在你的设备或你抄下的",["助记词","seed-phrase"],"里。常见的非托管钱包有手机/浏览器插件钱包和",["硬件钱包","hardware-wallet"],"。"],["好处是不受平台风险影响：交易所暂停提现、",["跑路","rug-pull"],"或冻结账户，都碰不到你钱包里的币；你也可以直接连接 ",["DEX","dex"],"、质押和各类链上应用。代价是责任全在自己身上，没有客服，没有“忘记密码”，助记词丢了或被盗，资产基本无法追回。"],"很多交易所 App 里也内置了 Web3 钱包，是否属于非托管，要看助记词或私钥是否真正由你掌握，以及能否导入到其他钱包软件中使用。"],"example":"假设你在交易所买了 2,000 USDT，提到自己的非托管钱包地址，扣掉 1 USDT 提现手续费，钱包到账 1,999 USDT。此后交易所即使暂停服务，这 1,999 USDT 仍在链上归你所有；但如果你把 12 个助记词拍照存进了网盘，网盘被盗后，别人只需几分钟就能把它全部转走。","mistakes":["以为钱包 App 能帮你找回资产，实际上丢了助记词，开发方也无能为力。","把助记词截图或存在聊天记录、云笔记里，等于把私钥交给了第三方。","把交易所内置的托管账户误当成自托管钱包，没弄清助记词到底在谁手里。"],"faq":[{"q":"非托管钱包比交易所更安全吗？","a":"它消除了平台跑路、冻结等风险，但把保管风险转到了你自己身上。助记词管理得当，安全性通常更高；管理不当，损失没人兜底。"},{"q":"非托管钱包可以直接买币吗？","a":"部分钱包集成了第三方买币或兑换服务，但本质上是钱包连接外部服务商或 DEX。更常见的做法是在交易所买好后再提到钱包。"}],"title":"什么是非托管钱包？自托管钱包的含义与风险","description":"了解非托管钱包（自托管钱包）的含义：私钥由谁掌握、与交易所托管账户的区别，以及新手保管助记词时最容易犯的错误。","related":[["custodial-wallet","托管钱包（Custodial Wallet）","托管钱包是由交易所或其他第三方代为保管私钥的钱包，你通过账户密码登录使用，资产实际由平台控制，便捷但要承担平台风险。"],["seed-phrase","助记词（Seed Phrase）","助记词是由 12 或 24 个英文单词组成的钱包备份，可以推导出钱包里的全部私钥，谁拿到助记词，谁就能控制这个钱包里的所有资产。"],["private-key","私钥（Private Key）","私钥是一串只有持有人知道的随机数字，用来对交易进行数字签名，证明你有权动用某个地址里的资产，私钥泄露就等于资产失控。"],["hardware-wallet","硬件钱包（Hardware Wallet）","硬件钱包是一种专门保管私钥的小型实体设备，私钥在设备内部生成并签名，从不传到电脑或手机上，是最常用的冷钱包形式。"]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"币到底在哪：交易所和钱包有什么不同？"},"coin":null,"tool":null,"cta":false},"multisig-wallet":{"slug":"multisig-wallet","cat":"wallets-security","en":"Multisig wallet","contentLocale":"zh-Hans","term":"多签钱包（Multisig Wallet）","aka":["多签钱包","多重签名钱包","Multisig","多签"],"short":"多签钱包是需要多把私钥中的若干把共同签名才能转出资产的钱包，例如“3 选 2”，常用于团队资金、DAO 金库和大额个人资产管理。","body":[["普通钱包一把",["私钥","private-key"],"就能动用全部资产，单点风险很大。多签钱包设定 M-of-N 规则：一共 N 把钥匙，至少 M 把签名才能执行交易。",["比特币","bitcoin"],"原生支持多签脚本，",["以太坊","ethereum"],"上常见的多签是基于",["智能合约","smart-contract"],"的方案，例如 Safe。"],["好处是一把钥匙丢失或泄露都不至于让资产失控，团队成员之间也能互相制衡。",["交易所","centralized-exchange"],["冷钱包","cold-wallet"],"、项目金库、DAO 资金普遍采用多签。"],"代价是操作更复杂：每笔转账要协调多人签名；钥匙分布、备份方案需要事先设计好；合约型多签还要考虑合约本身和前端界面的安全。"],"example":"假设一个三人团队用“3 选 2”多签管理 200,000 USDT，每人各保管一把私钥。某成员的电脑被黑，私钥泄露，但攻击者手里只有 1 把，达不到 2 把的门槛，无法转走资金。剩下两人立即签名，把资金转移到一个新的多签地址，整个过程无需等待第三人。","mistakes":["把多签的多把私钥都放在同一个人或同一台设备上，失去了分散的意义。","设置“2 选 2”却没有备份，任何一把丢失都会导致资产永久锁死。","签名时只确认“同意”，不核对交易的目标地址和调用内容。"],"faq":[{"q":"个人有必要用多签钱包吗？","a":"资产量较大时可以考虑，比如用两台硬件钱包加一份异地备份组成“3 选 2”。但它提高了操作复杂度，新手应先熟悉单签硬件钱包。"},{"q":"多签钱包就是 MPC 钱包吗？","a":"不是。多签在链上使用多把独立私钥；MPC 钱包把一把私钥分片计算，链上看起来仍是普通单签地址。两者目标相似，实现方式不同。"}],"title":"什么是多签钱包？M-of-N 多重签名原理","description":"多签钱包是什么？了解 M-of-N 多重签名如何分散私钥风险、DAO 和交易所为何使用多签，以及个人设置多签时容易踩的坑。","related":[["private-key","私钥（Private Key）","私钥是一串只有持有人知道的随机数字，用来对交易进行数字签名，证明你有权动用某个地址里的资产，私钥泄露就等于资产失控。"],["cold-wallet","冷钱包（冷存储）","冷钱包是把私钥保存在不联网环境中的钱包或存储方式，例如硬件钱包和离线生成的纸钱包，主要用于长期、安全地存放大额加密资产。"],["dao","DAO（去中心化自治组织）","DAO（去中心化自治组织）是通过智能合约和代币投票来管理资金与决策的组织形式，成员按持有的治理代币对提案投票，结果由链上规则或多签执行。"],["non-custodial-wallet","非托管钱包（自托管钱包）","非托管钱包是由你自己保管私钥或助记词的钱包，资产的控制权完全在你手里，没有任何平台能替你冻结、挪用或找回。"]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"币到底在哪：交易所和钱包有什么不同？"},"coin":null,"tool":null,"cta":false},"dao":{"slug":"dao","cat":"defi","en":"DAO (decentralized autonomous organization)","contentLocale":"zh-Hans","term":"DAO（去中心化自治组织）","aka":["DAO","去中心化自治组织","Decentralized autonomous organization"],"short":"DAO（去中心化自治组织）是通过智能合约和代币投票来管理资金与决策的组织形式，成员按持有的治理代币对提案投票，结果由链上规则或多签执行。","body":[["很多 ",["DeFi","defi"]," 协议在发展成熟后会把参数调整、资金使用、升级方案交给 DAO 决定。例如 Uniswap 等协议的代币持有者可以对提案投票，决定手续费开关、资金拨款等事项。"],["典型流程是：社区论坛讨论，提交正式提案，",["治理代币","governance-token"],"持有人在规定时间内投票，达到法定票数且赞成票过半后，通过时间锁或多签执行。有的投票在链上进行，有的用链下签名投票节省 ",["Gas 费","gas-fee"],"。"],"现实中 DAO 也有问题：投票率普遍不高，大户和项目方掌握多数票，执行仍依赖少数多签成员。法律地位在不同国家也不清晰，参与者需要了解各自所在地的规定。"],"example":"假设某 DAO 的金库有 5,000 万美元，治理规则要求提案获得至少 4,000 万票参与、且赞成票超过 50% 才能通过。一项拨款 200 万美元的提案最终有 4,500 万票参与，其中 2,600 万票赞成，赞成率约 57.8%，提案通过，并在 2 天时间锁结束后由合约自动转账。","mistakes":["以为买了治理代币就能分红或拿到协议收入，实际很多代币只有投票权。","以为 DAO 完全去中心化，忽略了少数大户和多签成员的实际控制力。","在钓鱼网站上“参与投票”，签下了恶意授权。"],"faq":[{"q":"DAO 和公司有什么区别？","a":"公司由董事会和管理层决策，股权和法律关系明确；DAO 由代币投票决策并通过合约执行，但法律身份和责任在多数地区仍不明确。"},{"q":"普通人怎么参与 DAO？","a":"持有该 DAO 的治理代币，在其治理页面连接钱包投票或委托投票权给代表。参与前确认是官方入口。"}],"title":"什么是 DAO？去中心化自治组织如何运作","description":"DAO 是什么意思？了解去中心化自治组织如何用治理代币投票、提案从讨论到执行的流程，以及 DAO 在投票集中和法律方面的问题。","related":[["governance-token","治理代币（Governance Token）","治理代币是赋予持有人对协议或 DAO 提案投票权的代币，例如 UNI、AAVE，持有越多投票权越大，但不一定代表能分享协议收入。"],["multisig-wallet","多签钱包（Multisig Wallet）","多签钱包是需要多把私钥中的若干把共同签名才能转出资产的钱包，例如“3 选 2”，常用于团队资金、DAO 金库和大额个人资产管理。"],["smart-contract","智能合约（Smart Contract）","智能合约是部署在区块链上、满足预设条件就自动执行的程序代码，DeFi、NFT 和链上代币都依靠它运行。"],["defi","DeFi（去中心化金融）","DeFi（去中心化金融）是指运行在区块链智能合约上的金融服务，比如交易、借贷、质押和收益聚合，用户用自己的钱包直接参与，无需银行或交易所作为中介。"]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"apr-vs-apy":{"slug":"apr-vs-apy","cat":"defi","en":"APR vs APY","contentLocale":"zh-Hans","term":"APR 和 APY 的区别","aka":["APR","APY","年化收益率","年化利率"],"short":"APR 是不计复利的年化收益率，APY 是计入复利后的年化收益率；同一个利率下，复利频率越高，APY 就比 APR 高得越多。","body":["APR（年化百分比利率）只是把周期利率简单乘以一年的周期数，比如日利率 0.03% 乘以 365 天约等于 10.95%。APY（年化百分比收益）则假设每期收益都会自动再投入、继续产生收益，所以数值更高。",[["交易所","centralized-exchange"],"理财、",["质押","staking"],"、",["DeFi","defi"]," 池子展示的年化可能用 APR，也可能用 APY，有的还会在页面上切换。比较两个产品时，先确认口径一致，再看收益是否以同一种币计价、是否浮动、是否需要手动复投。"],["在",["资金费率","funding-rate"],"、借贷利率等场景下，平台常给出某个周期的费率，再换算成年化，这通常是不计复利的 APR 口径，而且只代表当下水平，并不保证全年都能拿到。"]],"example":["假设你有 10,000 ",["USDT","usdt"],"，产品显示 APR 为 12%。如果不复利，一年后收益为 1,200 USDT。如果每天自动复利，APY 约为 (1 加 0.12 除以 365) 的 365 次方减 1，约等于 12.75%，一年后收益约 1,275 USDT，比单利多约 75 USDT。如果每月复利一次，APY 约为 12.68%。"],"mistakes":["把 APY 产品和 APR 产品的数字直接对比，判断哪个收益更高。","以为显示的年化是固定收益，其实大多随市场浮动。","忽略复投需要支付的 Gas 费，小额频繁复投反而降低收益。"],"faq":[{"q":"APR 和 APY 哪个更高？","a":"利率相同时，只要存在复利，APY 总是高于或等于 APR，复利越频繁差距越大。"},{"q":"理财页面的年化收益能信吗？","a":"它通常是根据近期数据或当前利率计算的估计值，实际收益会随市场、参与人数和奖励代币价格变化。"}],"title":"APR 和 APY 的区别是什么？年化收益怎么算","description":"APR 和 APY 有什么区别？用计算例子讲清单利年化与复利年化的换算方法，以及比较理财、质押和 DeFi 收益时要注意的口径。","related":[["staking","质押（Staking）","质押是把权益证明（PoS）区块链的代币锁定，用来支持网络验证并获得奖励的做法，你可以自己运行验证节点，也可以通过交易所或质押服务参与。"],["yield-farming","流动性挖矿（Yield Farming）","流动性挖矿是指把加密资产存入 DeFi 协议提供流动性或借贷，以赚取手续费、利息以及协议额外发放的代币奖励的做法。"],["crypto-earn","理财/赚币（Crypto Earn）","理财（赚币）是交易所提供的加密资产收益产品，把你账户里的闲置币放进活期或定期产品中，由平台通过借贷、质押或其他方式产生收益并按约定发放。"],["funding-rate","资金费率（Funding Rate）","资金费率是永续合约中多头和空头之间定期互相支付的费率，用来让永续合约价格贴近现货指数价格，正费率时多头付给空头。"]],"lesson":null,"coin":null,"tool":null,"cta":false},"algorithmic-stablecoin":{"slug":"algorithmic-stablecoin","cat":"stablecoins","en":"Algorithmic stablecoin","contentLocale":"zh-Hans","term":"算法稳定币（Algorithmic stablecoin）","aka":["算稳","算法型稳定币"],"short":"算法稳定币是主要依靠代码规则调节供应量、而不是靠足额现金或抵押品来维持1美元价格的稳定币，在信心崩溃时容易出现严重脱锚。","body":[["典型的算法稳定币会搭配一个",["波动性","volatility"],"代币：",["稳定币","stablecoin"],"低于1美元时，协议允许用户用1枚稳定币兑换价值1美元的波动代币，从而销毁稳定币、减少供应；高于1美元时则反向操作，增发稳定币。",["套利","arbitrage"],"者的买卖被设计成把价格推回锚定值。"],["问题在于，这种机制依赖市场持续相信波动代币有价值。一旦稳定币大幅",["脱锚","depeg"],"，大量用户兑换会让波动代币被疯狂增发、价格暴跌，进而让兑换出的“1美元价值”越来越不值钱，形成所谓的死亡螺旋。2022年5月 UST 和 LUNA 的崩盘就是这种机制失效的典型案例。"],"现在市场上也有部分抵押、部分算法的混合设计。判断时可以看：有没有可以随时赎回的足额储备、储备是什么资产、极端情况下谁来承担损失。"],"example":"假设某算法稳定币跌到0.98美元，你花980美元买入1,000枚，再按协议规则兑换成价值1,000美元的波动代币并立即卖出，理论上赚20美元，同时1,000枚稳定币被销毁。但如果很多人同时这样做，波动代币被大量增发，你卖出时它的价格可能已经下跌10%，到手只有900美元，反而亏损80美元，这正是死亡螺旋开始时的情形。","mistakes":["被高收益吸引，把算法稳定币当成和法币储备型稳定币一样安全的“美元”。","只看过去一直稳定在1美元，就忽视了机制在极端行情下失效的可能。","不了解兑换机制背后的波动代币，在脱锚初期加仓抄底。"],"faq":[{"q":"算法稳定币一定会崩盘吗？","a":"不是一定，但纯算法、缺乏足额储备的设计在信心危机下非常脆弱。是否可靠主要看储备是否充足、赎回渠道是否通畅。"},{"q":"UST为什么会脱锚？","a":"UST依靠与LUNA的兑换机制维持锚定，大规模赎回导致LUNA被大量增发、价格崩溃，兑换机制无法再托住UST的价格。"}],"title":"什么是算法稳定币？运作原理与死亡螺旋风险","description":"算法稳定币如何靠增发和销毁维持1美元？本文用数字讲解套利机制、死亡螺旋的形成，以及UST崩盘给出的教训。","related":[["depeg","脱锚（Depeg）","脱锚是指稳定币或锚定类资产的市场价格明显偏离它承诺跟随的价值，例如本应等于1美元的稳定币跌到0.95美元或涨到1.03美元。"],["stablecoin","稳定币（Stablecoin）","稳定币是一种设计为与美元等法币或资产保持稳定兑换比例的加密货币，最常见的是 1 枚兑 1 美元的 USDT 和 USDC，是加密交易中的主要计价和结算工具。"],["crypto-backed-stablecoin","加密资产抵押型稳定币（Crypto-backed stablecoin）","加密资产抵押型稳定币是用户把ETH等加密资产超额抵押进智能合约后铸造出来的稳定币，DAI是最典型的例子，抵押品不足时仓位会被清算。"],["synthetic-dollar","合成美元（Synthetic dollar）","合成美元是一种通过持有现货加密资产、同时在永续合约上开等额空单实现Delta中性，从而让价值稳定在约1美元的稳定币，Ethena的USDe是代表。"]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT是美元吗？为什么买币常见它？"},"coin":null,"tool":null,"cta":false}});
